const $ = (id)=>document.getElementById(id);
const esc = (v)=>String(v ?? "").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]));
const fmtNum = (n,d=0)=>Number.isFinite(Number(n)) ? Number(n).toLocaleString("fr-FR",{maximumFractionDigits:d,minimumFractionDigits:d}) : "—";
const fmtPct = (x)=>Number.isFinite(Number(x)) ? (Number(x)*100).toLocaleString("fr-FR",{maximumFractionDigits:1})+" %" : "—";
