function toast(message,kind="info"){
  const t=$("toast"); t.textContent=message; t.style.background=kind==="error"?"#9f2f37":kind==="ok"?"#0e6e4c":"#16324f"; t.classList.add("show");
  clearTimeout(toast._timer); toast._timer=setTimeout(()=>t.classList.remove("show"),4200);
}
function setLoading(on){state.loading=on; document.body.classList.toggle("loading-overlay",on);}
function setStatus(text,mode="snapshot"){
  const el=$("sourceStatus"); el.className="status-pill "+mode; el.innerHTML=(mode==="live"?'<i class="fa-solid fa-cloud"></i> ':mode==="error"?'<i class="fa-solid fa-triangle-exclamation"></i> ':'<i class="fa-solid fa-table-cells"></i> ')+esc(text);
}
function normalText(v){return String(v??"").trim();}
function parseLeadingNumber(v){const m=normalText(v).replace(",",".").match(/^\s*(-?\d+(?:\.\d+)?)/); return m?Number(m[1]):NaN;}
function unique(arr){return [...new Set(arr.filter(v=>normalText(v)!=="").map(normalText))];}
function qByPath(path){return catalog().find(q=>q.fullPath===path);}
function isConfidential(q){return !q || q.confidential || String(q.analysisType).startsWith("CONFIDENTIEL");}

function lookupRawValue(raw,q){
  if(!raw || !q) return "";
  if(Object.prototype.hasOwnProperty.call(raw,q.fullPath)) return raw[q.fullPath];
  if(Object.prototype.hasOwnProperty.call(raw,q.name)) return raw[q.name];
  const keys=Object.keys(raw); const fp=q.fullPath.toLowerCase(); const name=q.name.toLowerCase();
  for(const k of keys){const lk=k.toLowerCase(); if(lk===fp || lk.endsWith("/"+fp) || lk.endsWith("/"+name)) return raw[k];}
  return "";
}
function normalizeRecord(raw,index){
  const values={};
  for(const q of catalog()){
    if(isConfidential(q)) continue;
    const v=lookupRawValue(raw,q);
    if(v!==undefined && v!==null && String(v).trim()!=="") values[q.fullPath]=v;
  }
  return {id:raw._id ?? raw.id ?? raw._uuid ?? (index+1), values};
}
function extractRecordArray(obj){
  if(Array.isArray(obj)) return obj;
  for(const key of ["results","records","data","rows"]){if(Array.isArray(obj?.[key])) return obj[key];}
  throw new Error("Le JSON ne contient pas de tableau d’enregistrements reconnu (results, records, data ou tableau racine).");
}

async function fetchKoboJsonWithFallback(target){
  const providers=[
    {name:"Direct KoboToolbox",url:target},
    {name:"AllOrigins",url:"https://api.allorigins.win/raw?url="+encodeURIComponent(target)},
    {name:"CodeTabs",url:"https://api.codetabs.com/v1/proxy?quest="+encodeURIComponent(target)},
    {name:"corsproxy.io",url:"https://corsproxy.io/?"+encodeURIComponent(target)}
  ];
  const errors=[];
  for(const provider of providers){
    try{
      const response=await fetch(provider.url,{method:"GET",headers:{Accept:"application/json"},credentials:"omit",cache:"no-store"});
      if(!response.ok){errors.push(`${provider.name}: HTTP ${response.status}`);continue;}
      try{return {body:await response.json(),provider:provider.name};}
      catch(_){errors.push(`${provider.name}: réponse non JSON`);}
    }catch(e){errors.push(`${provider.name}: ${e?.message||e}`);}
  }
  throw new Error(`Toutes les méthodes de connexion KoboToolbox ont échoué. ${errors.join(" | ")}`);
}

async function fetchAllKobo(role){
  const uid=CONFIG[role].assetUid;
  let url=`https://kf.kobotoolbox.org/api/v2/assets/${encodeURIComponent(uid)}/data.json?limit=1000&_t=${Date.now()}`;
  const all=[]; const providers=[]; let pages=0;
  while(url && pages<100){
    const result=await fetchKoboJsonWithFallback(url);
    if(!providers.includes(result.provider))providers.push(result.provider);
    const body=result.body;
    const rows=Array.isArray(body)?body:(body.results||[]); all.push(...rows); pages++;
    if(Array.isArray(body))url=null;
    else if(body && typeof body.next==="string" && body.next){try{url=new URL(body.next,"https://kf.kobotoolbox.org").href;}catch(_){url=null;}}
    else url=null;
  }
  if(url && pages>=100)throw new Error("Pagination Kobo interrompue après 100 pages par sécurité.");
  return {rows:all,providers,pages};
}

function useSnapshot(){
  state.source="snapshot"; state.records=null; state.filteredRecords=[];
  setStatus(`Snapshot agrégé DATA MUST SPEAK — ${DMS_DATA.meta.snapshotCounts[state.role]} soumissions`,"snapshot");
  $("sourceMessage").textContent="Aperçu agrégé issu du classeur DATA MUST SPEAK SEEPE. Les analyses globales sont disponibles ; la recherche ligne par ligne et les regroupements détaillés nécessitent KoboToolbox ou un JSON.";
  updateSourceCapabilities(); renderAll();
}
async function syncKobo(){
  try{
    setLoading(true); setStatus("Synchronisation KoboToolbox en cours…","snapshot");
    const result=await fetchAllKobo(state.role); const raw=result.rows; state.records=raw.map(normalizeRecord); state.source="kobo"; state.filteredRecords=[...state.records];
    setStatus(`KoboToolbox actif — ${state.records.length} soumission(s)`,"live");
    $("sourceMessage").textContent=`Données détaillées synchronisées depuis l’asset ${CONFIG[state.role].assetUid} via ${result.providers.join(" + ") || "Direct KoboToolbox"} (${result.pages} page(s)). Les filtres et regroupements géographiques sont actifs.`;
    updateSourceCapabilities(); renderAll(); toast(`${state.records.length} soumission(s) Kobo chargée(s).`,"ok");
  }catch(e){setStatus("Échec de la synchronisation KoboToolbox","error"); $("sourceMessage").textContent=e.message; toast(e.message,"error");}
  finally{setLoading(false);}
}
async function importJson(file){
  try{
    setLoading(true); const text=await file.text(); const obj=JSON.parse(text); const raw=extractRecordArray(obj); state.records=raw.map(normalizeRecord); state.filteredRecords=[...state.records]; state.source="json";
    setStatus(`JSON actif — ${state.records.length} soumission(s)`,"live"); $("sourceMessage").textContent=`Fichier ${file.name} chargé. Tous les graphiques, tableaux, filtres et regroupements utilisent maintenant uniquement ces données.`;
    updateSourceCapabilities(); renderAll(); toast(`JSON importé : ${state.records.length} ligne(s).`,"ok");
  }catch(e){toast(`Import JSON impossible : ${e.message}`,"error");}
  finally{setLoading(false); $("jsonImport").value="";}
}

function getLiveValues(path,records=state.records){return (records||[]).map(r=>r.values[path]).filter(v=>normalText(v)!=="");}
function distributionFromValues(values,limit=100){
  const m=new Map(); for(const v0 of values){const v=normalText(v0); if(!v) continue; m.set(v,(m.get(v)||0)+1);} return [...m.entries()].sort((a,b)=>b[1]-a[1]).slice(0,limit);
}
function aggregateQuestion(q,records=state.records){
  if(!q) return {n:0,missing:0};
  if(!records && state.source==="snapshot") return snapshotAgg()[q.fullPath] || {n:0,missing:DMS_DATA.meta.snapshotCounts[state.role]};
  const vals=getLiveValues(q.fullPath,records); const total=(records||[]).length; const item={n:vals.length,missing:Math.max(0,total-vals.length)};
  if(q.analysisType==="TEXTE"){item.textHidden=true; return item;}
  if(["SCORE_4","SCORE_5","NUMERIQUE"].includes(q.analysisType)){
    const nums=vals.map(parseLeadingNumber).filter(Number.isFinite); if(nums.length){item.mean=nums.reduce((a,b)=>a+b,0)/nums.length;item.min=Math.min(...nums);item.max=Math.max(...nums);item.numericN=nums.length;}
    if(q.analysisType.startsWith("SCORE")) item.distribution=Object.fromEntries(distributionFromValues(vals,30));
  } else item.distribution=Object.fromEntries(distributionFromValues(vals,50));
  return item;
}
function distEntries(agg){return Object.entries(agg?.distribution||{}).sort((a,b)=>b[1]-a[1]);}
function yesLike(s){const x=normalText(s).toLowerCase();return x==="oui"||x==="yes"||x==="1"||x==="true"||x.startsWith("oui ")||x.startsWith("oui,")||x.startsWith("oui-");}
function noLike(s){const x=normalText(s).toLowerCase();return x==="non"||x==="no"||x==="0"||x==="false"||x.startsWith("non ")||x.startsWith("non,")||x.startsWith("non-");}
function rateYes(path){
  const q=qByPath(path); if(!q)return NaN; const a=aggregateQuestion(q); const e=distEntries(a); const den=e.reduce((s,[,n])=>s+n,0); const yes=e.reduce((s,[v,n])=>s+(yesLike(v)?n:0),0); return den?yes/den:NaN;
}
function ratePositive(path){
  const q=qByPath(path); if(!q)return NaN; const a=aggregateQuestion(q); const e=distEntries(a); const den=e.reduce((s,[,n])=>s+n,0); if(!den)return NaN;
  let pos=0; for(const [v,n] of e){const x=normalText(v).toLowerCase(); if(yesLike(v)||x.includes("souvent")||x.includes("toujours")||x.includes("réguli")||x.includes("reguli"))pos+=n;} return pos/den;
}
function scorePositive(path){const q=qByPath(path); const a=aggregateQuestion(q); if(!q||!Number.isFinite(a.mean))return NaN; const max=q.scoreMax||5; return Math.max(0,Math.min(1,(a.mean-(max>=5?1:0))/(max-(max>=5?1:0)||1)));}
function distributionForPath(path){const q=qByPath(path);return q?distEntries(aggregateQuestion(q)):[];}
function geoDistribution(path){
  if(state.records){return distributionFromValues(getLiveValues(path),200);}
  const ex=execSnapshot(); if(path.endsWith('/DREN'))return Object.entries(ex.dren||{}); if(path.endsWith('/CISCO'))return Object.entries(ex.cisco||{}); if(path.endsWith('/ZAP'))return Object.entries(ex.zap||{}); return [];
}
function timelineDistribution(){
  if(state.records)return distributionFromValues(getLiveValues("LOCALISATION/DATE_ENQ"),500).sort((a,b)=>a[0].localeCompare(b[0]));
  return Object.entries(execSnapshot().timeline||{}).sort((a,b)=>a[0].localeCompare(b[0]));
}
function totalRecords(){return state.records?state.records.length:DMS_DATA.meta.snapshotCounts[state.role];}
function completionRate(){
  const qs=catalog().filter(q=>!isConfidential(q)&&q.filled!=="NON"); if(!qs.length)return NaN;
  if(state.records){let answered=0; for(const r of state.records)for(const q of qs)if(normalText(r.values[q.fullPath]))answered++; return answered/(state.records.length*qs.length||1);}
  let answered=0; for(const q of qs) answered+=(snapshotAgg()[q.fullPath]?.n||0); return answered/(totalRecords()*qs.length||1);
}
function capacityRows(){return CONFIG[state.role].capacity.map(([label,path,max])=>{const q=qByPath(path),a=aggregateQuestion(q);return [label,Number.isFinite(a.mean)?a.mean:null,max];});}
function themeIndexRows(){
  const rows=[]; for(const [prefix,label] of THEME_MAP){const qs=catalog().filter(q=>q.fullPath.startsWith(prefix)&&!isConfidential(q));const vals=[];
    for(const q of qs){const a=aggregateQuestion(q); if(!a||!a.n)continue; if(q.analysisType==="OUI_NON"){const den=distEntries(a).reduce((s,[,n])=>s+n,0);const yes=distEntries(a).reduce((s,[v,n])=>s+(yesLike(v)?n:0),0);if(den)vals.push(yes/den*100);} else if(q.analysisType.startsWith("SCORE")&&Number.isFinite(a.mean)){const max=q.scoreMax||5;vals.push(a.mean/max*100);} }
    rows.push([label,vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null,vals.length]);
  } return rows;
}

function destroyChart(id){if(state.charts[id]){state.charts[id].destroy();delete state.charts[id];}}
function makeChart(id,type,labels,data,label,opts={}){
  destroyChart(id); const el=$(id); if(!el||typeof Chart==="undefined")return;
  state.charts[id]=new Chart(el,{type,data:{labels,datasets:[{label,data,borderWidth:1.5,fill:type==="line"?false:undefined,tension:type==="line"?.25:undefined}]},options:{responsive:true,maintainAspectRatio:false,indexAxis:opts.horizontal?"y":"x",plugins:{legend:{display:opts.legend??(type==="pie"||type==="doughnut"||type==="radar"),position:"bottom"},tooltip:{callbacks:{label:(ctx)=>opts.percent?`${ctx.dataset.label||""}: ${fmtNum(ctx.raw,1)} %`:`${ctx.dataset.label||""}: ${fmtNum(ctx.raw,opts.decimals||0)}`}}},scales:(type==="pie"||type==="doughnut"||type==="radar")?{}:{y:{beginAtZero:true,suggestedMax:opts.max||undefined,ticks:{callback:v=>opts.percent?v+" %":v}},x:{ticks:{autoSkip:true,maxRotation:45,minRotation:0}}}}});
}
function makeRadar(id,labels,data,label,max=5){destroyChart(id);const el=$(id);if(!el||typeof Chart==="undefined")return;state.charts[id]=new Chart(el,{type:"radar",data:{labels,datasets:[{label,data,fill:true,borderWidth:2,pointRadius:3}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:"bottom"}},scales:{r:{beginAtZero:true,min:0,max,ticks:{stepSize:1}}}}});}
function miniTable(target,headers,rows){const el=$(target);if(!el)return;el.innerHTML=`<table class="mini-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
function dataTable(target,headers,rows){const el=$(target);if(!el)return;el.innerHTML=`<table class="data-table"><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c?.html?c.html:esc(c)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="muted">Aucune donnée.</td></tr>`}</tbody></table>`;}

function renderKpis(){
  const cfg=CONFIG[state.role]; const gD=geoDistribution(cfg.geoPaths.DREN).length; const gC=geoDistribution(cfg.geoPaths.CISCO).length; const last=timelineDistribution().slice(-1)[0]?.[0]||"—";
  const cards=[
    [state.role==="CISCO"?"Soumissions CISCO":"Soumissions Chefs ZAP",fmtNum(totalRecords()),state.source==="snapshot"?"snapshot DATA MUST SPEAK":"source détaillée active",""],
    ["DREN couvertes",fmtNum(gD),"zones avec au moins une réponse","green"],
    ["CISCO couvertes",fmtNum(gC),"unités avec au moins une réponse","green"],
    [state.role==="ZAP"?"ZAP couvertes":"Complétude moyenne",state.role==="ZAP"?fmtNum(geoDistribution(cfg.geoPaths.ZAP).length):fmtPct(completionRate()),state.role==="ZAP"?"ZAP identifiées":"questions renseignées","amber"]
  ];
  for(const [label,path,kind] of cfg.kpis.slice(0,4)){
    let v=kind==="yes"?rateYes(path):kind==="scorePositive"?scorePositive(path):ratePositive(path); cards.push([label,fmtPct(v),"part favorable / renseignée",Number.isFinite(v)&&v>=.7?"green":"amber"]);
  }
  cards.push(["Dernière date d'enquête",last,"date la plus récente observée","green"]);
  $("kpiGrid").innerHTML=cards.slice(0,8).map(([l,v,n,c])=>`<article class="kpi-card ${c||''}"><div class="kpi-label">${esc(l)}</div><div class="kpi-value">${esc(v)}</div><div class="kpi-note">${esc(n)}</div></article>`).join('');
}
function renderDashboard(){
  const cfg=CONFIG[state.role]; const scope=state.scope||"DREN";
  $("dashboardTitle").textContent=`Tableau de bord exécutif — ${scope} • Questionnaire ${state.role}`;
  $("dashboardSubtitle").textContent=`Analyse territoriale ${scope} • ${cfg.subtitle}`;
  renderKpis();

  const available={DREN:cfg.geoPaths.DREN,CISCO:cfg.geoPaths.CISCO,ZAP:cfg.geoPaths.ZAP};
  const primaryPath=available[scope]||cfg.geoPaths.DREN;
  const secondaryScope=scope==="DREN"?"CISCO":(scope==="CISCO"?"DREN":"CISCO");
  const secondaryPath=available[secondaryScope]||cfg.geoPaths.DREN;
  const primary=geoDistribution(primaryPath).slice(0,30);
  const secondary=geoDistribution(secondaryPath).slice(0,30);
  $("primaryGeoTitle").textContent=`Réponses par ${scope}`;
  $("primaryGeoSubtitle").textContent=`Onglet ${scope} — couverture territoriale`;
  makeChart("chartDren","bar",primary.map(x=>x[0]),primary.map(x=>x[1]),"Réponses",{horizontal:primary.length>8});
  miniTable("tableDren",[scope,"Réponses"],primary.map(x=>[x[0],fmtNum(x[1])]));
  $("secondaryGeoTitle").textContent=`Réponses par ${secondaryScope}`;
  $("secondaryGeoSubtitle").textContent=`Ventilation complémentaire depuis l’onglet ${scope}`;
  makeChart("chartCisco","bar",secondary.map(x=>x[0]),secondary.map(x=>x[1]),"Réponses",{horizontal:true});
  miniTable("tableCisco",[secondaryScope,"Réponses"],secondary.map(x=>[x[0],fmtNum(x[1])]));

  let th=[];
  if(scope==="ZAP" && cfg.geoPaths.ZAP){
    th=geoDistribution(cfg.geoPaths.ZAP).slice(0,30); $("thirdGeoTitle").textContent="Top des ZAP";$("thirdGeoSubtitle").textContent="Détail de proximité";
    makeChart("chartThird","bar",th.map(x=>x[0]),th.map(x=>x[1]),"Réponses",{horizontal:true});miniTable("tableThird",["ZAP","Réponses"],th.map(x=>[x[0],fmtNum(x[1])]));
  } else {
    th=distributionForPath("consentment_bref/formation_mars");$("thirdGeoTitle").textContent="Participation à la formation TDB";$("thirdGeoSubtitle").textContent=`Indicateur complémentaire — ${scope}`;
    makeChart("chartThird","doughnut",th.map(x=>x[0]),th.map(x=>x[1]),"Réponses",{legend:true});miniTable("tableThird",["Réponse","Effectif"],th.map(x=>[x[0],fmtNum(x[1])]));
  }
  const tl=timelineDistribution(); makeChart("chartTimeline","line",tl.map(x=>x[0]),tl.map(x=>x[1]),"Soumissions",{}); miniTable("tableTimeline",["Date","Soumissions"],tl.slice(-30).map(x=>[x[0],fmtNum(x[1])]));
  const cap=capacityRows(); makeRadar("chartCapacity",cap.map(x=>x[0]),cap.map(x=>x[1]??0),"Score moyen",state.role==="CISCO"?4:5); miniTable("tableCapacity",["Compétence","Moyenne","Max"],cap.map(x=>[x[0],x[1]==null?"—":fmtNum(x[1],2),x[2]]));
  const themes=themeIndexRows(); makeChart("chartThemes","bar",themes.map(x=>x[0]),themes.map(x=>x[1]??0),"Indice",{percent:true,max:100,horizontal:true,decimals:1}); miniTable("tableThemes",["Thème","Indice","Questions utilisées"],themes.map(x=>[x[0],x[1]==null?"—":fmtNum(x[1],1)+" %",x[2]]));
}

function populateQuestionControls(preserve=true){
  const qs=catalog().filter(q=>!isConfidential(q)); const themes=unique(qs.map(q=>q.theme)).sort((a,b)=>a.localeCompare(b,"fr"));
  const prevTheme=preserve?$("themeSelect").value:""; $("themeSelect").innerHTML='<option value="">Tous les thèmes</option>'+themes.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join(''); if(themes.includes(prevTheme))$("themeSelect").value=prevTheme;
  const theme=$("themeSelect").value; const filtered=qs.filter(q=>!theme||q.theme===theme); const prev=preserve?$("questionSelect").value:CONFIG[state.role].defaultQuestion;
  $("questionSelect").innerHTML=filtered.map(q=>`<option value="${esc(q.fullPath)}">${esc(q.order+'. '+q.label)}</option>`).join('');
  if(filtered.some(q=>q.fullPath===prev))$("questionSelect").value=prev; else if(filtered.length)$("questionSelect").value=filtered[0].fullPath;
  state.selectedQuestion=$("questionSelect").value;
}
function updateGroupOptions(){
  const live=!!state.records; const z=$('groupModeSelect').querySelector('option[value="ZAP"]'); if(z)z.disabled=state.role!=="ZAP"||!live;
  for(const v of ["DREN","CISCO"]){const o=$('groupModeSelect').querySelector(`option[value="${v}"]`);if(o)o.disabled=!live;}
  if(!live && $("groupModeSelect").value!=="all")$("groupModeSelect").value="all";
}
function groupedQuestionRows(q,groupPath){
  const groups=new Map(); for(const r of state.records||[]){const g=normalText(r.values[groupPath])||"Non renseigné";if(!groups.has(g))groups.set(g,[]);groups.get(g).push(r);}
  const rows=[]; for(const [g,recs] of groups){const a=aggregateQuestion(q,recs);const rate=a.n/(recs.length||1);if(["SCORE_4","SCORE_5","NUMERIQUE"].includes(q.analysisType)){rows.push({group:g,n:a.n,total:recs.length,rate,metric:Number.isFinite(a.mean)?a.mean:null,detail:Number.isFinite(a.mean)?`Moyenne ${fmtNum(a.mean,2)}`:"—"});}
    else {const e=distEntries(a);const dom=e[0];rows.push({group:g,n:a.n,total:recs.length,rate,metric:rate*100,detail:dom?`${dom[0]} (${fmtPct(dom[1]/Math.max(1,a.n))})`:"—"});}}
  return rows.sort((a,b)=>(b.metric??-Infinity)-(a.metric??-Infinity));
}
function renderQuestion(){
  const q=qByPath($("questionSelect").value); if(!q)return; state.selectedQuestion=q.fullPath; const a=aggregateQuestion(q); const total=totalRecords();
  $("questionTypeBadge").textContent=q.analysisType; $("questionLabel").textContent=q.label; $("questionMeta").textContent=`${q.theme} • Kobo: ${q.fullPath} • Colonne DMS ${q.column} • ${q.snapshotResponses} réponse(s) dans le classeur de référence`;
  const kpis=[["Réponses",fmtNum(a.n)],["Manquantes",fmtNum(a.missing)],["Taux de réponse",fmtPct(a.n/Math.max(1,a.n+a.missing))]]; if(Number.isFinite(a.mean))kpis.push(["Moyenne",fmtNum(a.mean,2)+(q.scoreMax?` / ${q.scoreMax}`:"")]); else kpis.push(["Type",q.xlsType||q.analysisType]);
  $("questionKpis").innerHTML=kpis.map(([l,v])=>`<div class="question-kpi"><span>${esc(l)}</span><strong>${esc(v)}</strong></div>`).join('');
  const mode=$("groupModeSelect").value; let rows=[]; let labels=[]; let data=[]; let tableHeaders=[]; let tableRows=[]; let insight="";
  if(mode==="all"){
    if(q.analysisType==="TEXTE"){
      destroyChart("chartQuestion"); insight=`<h4>Réponses texte</h4><p>${fmtNum(a.n)} réponse(s) renseignée(s). Pour éviter d’exposer des textes libres individuels dans le snapshot public, leur contenu n’est pas embarqué. Le comptage reste disponible.</p>`;tableHeaders=["Mesure","Valeur"];tableRows=[["Réponses renseignées",fmtNum(a.n)],["Réponses manquantes",fmtNum(a.missing)]];
    } else if(q.analysisType==="NUMERIQUE" && !a.distribution){
      labels=["Minimum","Moyenne","Maximum"];data=[a.min??0,a.mean??0,a.max??0];makeChart("chartQuestion","bar",labels,data,"Valeur",{decimals:2});tableHeaders=["Mesure","Valeur"];tableRows=[["N numérique",fmtNum(a.numericN||a.n)],["Minimum",fmtNum(a.min,2)],["Moyenne",fmtNum(a.mean,2)],["Maximum",fmtNum(a.max,2)]];insight=`<h4>Lecture</h4><p>La moyenne observée est <strong>${fmtNum(a.mean,2)}</strong>, avec un minimum de ${fmtNum(a.min,2)} et un maximum de ${fmtNum(a.max,2)}.</p>`;
    } else {
      rows=distEntries(a);labels=rows.map(x=>x[0]);data=rows.map(x=>x[1]);const ct=$("questionChartType").value;makeChart("chartQuestion",ct,labels,data,"Réponses",{legend:ct==="pie"||ct==="doughnut",horizontal:ct==="bar"&&labels.length>8});tableHeaders=["Réponse / modalité","Effectif","Part"];tableRows=rows.map(([v,n])=>[v,fmtNum(n),fmtPct(n/Math.max(1,a.n))]);const top=rows[0];insight=`<h4>Lecture rapide</h4><p>${top?`La modalité la plus fréquente est <strong>${esc(top[0])}</strong> avec ${fmtNum(top[1])} réponse(s), soit ${fmtPct(top[1]/Math.max(1,a.n))}.`:"Aucune réponse exploitable."}</p><p>Taux de réponse : <strong>${fmtPct(a.n/Math.max(1,a.n+a.missing))}</strong>.</p>`;
    }
    $("questionTableCaption").textContent=state.source==="snapshot"?"Snapshot agrégé DATA MUST SPEAK":"Données détaillées actives";
  } else {
    if(!state.records){$("groupModeSelect").value="all";return renderQuestion();}
    const path=CONFIG[state.role].geoPaths[mode]; const gr=groupedQuestionRows(q,path); labels=gr.map(x=>x.group); data=gr.map(x=>x.metric??0); makeChart("chartQuestion",$("questionChartType").value==="line"?"line":"bar",labels,data,["SCORE_4","SCORE_5","NUMERIQUE"].includes(q.analysisType)?"Moyenne":"Taux de réponse (%)",{horizontal:labels.length>10,percent:!["SCORE_4","SCORE_5","NUMERIQUE"].includes(q.analysisType),decimals:2}); tableHeaders=[mode,"Réponses","Total groupe","Taux de réponse","Indicateur / modalité dominante"];tableRows=gr.map(x=>[x.group,fmtNum(x.n),fmtNum(x.total),fmtPct(x.rate),x.detail]); insight=`<h4>Analyse groupée par ${esc(mode)}</h4><p>${gr.length} groupe(s) comparés. Le tableau présente les effectifs exacts, le taux de réponse et ${["SCORE_4","SCORE_5","NUMERIQUE"].includes(q.analysisType)?"la moyenne":"la modalité dominante"} pour chaque groupe.</p>`;$("questionTableCaption").textContent=`Réponse groupée par ${mode}`;
  }
  $("questionInsight").innerHTML=insight; dataTable("questionTable",tableHeaders,tableRows);
}

function updateSourceCapabilities(){updateGroupOptions();const live=!!state.records;$("searchAvailability").innerHTML=live?`<strong>Recherche détaillée active.</strong> ${fmtNum(state.records.length)} enregistrement(s) disponibles depuis ${state.source==="kobo"?"KoboToolbox":"le fichier JSON"}.`:`<strong>Snapshot agrégé actif.</strong> Les données individuelles ne sont volontairement pas intégrées. Cliquez sur « Synchroniser depuis KoboToolbox » ou importez un JSON pour activer les filtres ligne par ligne.`; renderSearchFilters();}
function recordVal(r,path){return normalText(r?.values?.[path]);}
function renderSearchFilters(){
  const cfg=CONFIG[state.role]; const recs=state.records||[]; const fill=(id,path)=>{const el=$(id),cur=el.value; const vals=unique(recs.map(r=>recordVal(r,path))).sort((a,b)=>a.localeCompare(b,"fr"));el.innerHTML='<option value="">Toutes</option>'+vals.map(v=>`<option>${esc(v)}</option>`).join('');if(vals.includes(cur))el.value=cur;}; fill("filterDren",cfg.geoPaths.DREN);fill("filterCisco",cfg.geoPaths.CISCO);fill("filterZap",cfg.geoPaths.ZAP||"__none__");$("filterZapLabel").style.display=state.role==="ZAP"?"block":"none"; if(!state.records) dataTable("searchTable",["Information"],[["Activez une source détaillée pour afficher les enregistrements."]]); else applySearchFilters();
}
function applySearchFilters(){
  if(!state.records){state.filteredRecords=[];$("filteredCount").textContent="0";$("filteredSource").textContent="— snapshot agrégé";return;}
  const cfg=CONFIG[state.role],fd=$("filterDren").value,fc=$("filterCisco").value,fz=$("filterZap").value,from=$("filterDateFrom").value,to=$("filterDateTo").value,id=normalText($("filterId").value).toLowerCase();
  state.filteredRecords=state.records.filter(r=>{const d=recordVal(r,"LOCALISATION/DATE_ENQ");return(!fd||recordVal(r,cfg.geoPaths.DREN)===fd)&&(!fc||recordVal(r,cfg.geoPaths.CISCO)===fc)&&(state.role!=="ZAP"||!fz||recordVal(r,cfg.geoPaths.ZAP)===fz)&&(!from||d>=from)&&(!to||d<=to)&&(!id||String(r.id).toLowerCase().includes(id));});
  $("filteredCount").textContent=fmtNum(state.filteredRecords.length);$("filteredSource").textContent=`— ${state.source}`;
  const qs=catalog().filter(q=>!isConfidential(q)&&q.filled!=="NON"); const rows=state.filteredRecords.slice(0,500).map(r=>{let ans=0;for(const q of qs)if(recordVal(r,q.fullPath))ans++;return [r.id,recordVal(r,"LOCALISATION/DATE_ENQ")||"—",recordVal(r,cfg.geoPaths.DREN)||"—",recordVal(r,cfg.geoPaths.CISCO)||"—",state.role==="ZAP"?(recordVal(r,cfg.geoPaths.ZAP)||"—"):"—",fmtPct(ans/Math.max(1,qs.length))];});
  dataTable("searchTable",["ID soumission","Date enquête","DREN","CISCO","ZAP","Complétude utile"],rows);
}
function resetSearch(){for(const id of ["filterDren","filterCisco","filterZap","filterDateFrom","filterDateTo","filterId"])$(id).value="";applySearchFilters();}

function populateCatalogFilters(){const qs=catalog(); const types=unique(qs.map(q=>q.analysisType)).sort();const themes=unique(qs.map(q=>q.theme)).sort((a,b)=>a.localeCompare(b,"fr"));$("catalogType").innerHTML='<option value="">Tous les types</option>'+types.map(v=>`<option>${esc(v)}</option>`).join('');$("catalogTheme").innerHTML='<option value="">Tous les thèmes</option>'+themes.map(v=>`<option>${esc(v)}</option>`).join('');}
function renderCatalog(){const term=normalText($("catalogSearch").value).toLowerCase(),typ=$("catalogType").value,theme=$("catalogTheme").value;const qs=catalog().filter(q=>(!typ||q.analysisType===typ)&&(!theme||q.theme===theme)&&(!term||[q.label,q.fullPath,q.name,q.column,q.theme].join(' ').toLowerCase().includes(term)));$("catalogCount").textContent=fmtNum(catalog().length);const rows=qs.map(q=>[q.order,q.theme,q.label,q.analysisType,q.column,q.name,q.snapshotResponses,q.confidential?{html:'<span class="confidential">Masqué / confidentiel</span>'}:"Analysable"]);dataTable("catalogTable",["#","Thème","Question / libellé","Type analyse","Colonne","NAME Kobo","Réponses snapshot","Statut"],rows);}

function exportBlob(filename,content,type){const blob=new Blob([content],{type});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=filename;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},500);}
function timestamp(){const d=new Date(),p=n=>String(n).padStart(2,"0");return `${d.getFullYear()}${p(d.getMonth()+1)}${p(d.getDate())}_${p(d.getHours())}${p(d.getMinutes())}${p(d.getSeconds())}`;}
function csv(rows){return '\ufeff'+rows.map(r=>r.map(v=>`"${String(v??"").replace(/"/g,'""')}"`).join(';')).join('\r\n');}
function dashboardSummary(){return {role:state.role,source:state.source,generated_at:new Date().toISOString(),records:totalRecords(),dren:geoDistribution(CONFIG[state.role].geoPaths.DREN),cisco:geoDistribution(CONFIG[state.role].geoPaths.CISCO),zap:state.role==="ZAP"?geoDistribution(CONFIG[state.role].geoPaths.ZAP):[],timeline:timelineDistribution(),capacity:capacityRows(),themes:themeIndexRows()};}
function exportDashboard(kind){const s=dashboardSummary(),base=`SUIVI_IOV_SPSSE_${state.role}_${timestamp()}`;if(kind==="dashboard-json")exportBlob(base+'.json',JSON.stringify(s,null,2),'application/json;charset=utf-8');else{const rows=[["Indicateur","Valeur"],["Rôle",state.role],["Source",state.source],["Soumissions",totalRecords()],[],["DREN","Réponses"],...s.dren,[],["CISCO","Réponses"],...s.cisco];if(s.zap.length)rows.push([], ["ZAP","Réponses"], ...s.zap);rows.push([], ["Date","Soumissions"], ...s.timeline, [], ["Compétence","Moyenne","Maximum"], ...s.capacity.map(x=>[x[0],x[1]??"",x[2]]), [], ["Thème","Indice (%)","Questions utilisées"], ...s.themes.map(x=>[x[0],x[1]??"",x[2]]));exportBlob(base+'.csv',csv(rows),'text/csv;charset=utf-8');}}
function exportQuestion(kind){const q=qByPath($("questionSelect").value),a=aggregateQuestion(q);if(!q)return;const mode=$("groupModeSelect").value;let grouped=[];if(mode!=="all"&&state.records){const gp=CONFIG[state.role].geoPaths[mode];grouped=groupedQuestionRows(q,gp);}const obj={role:state.role,source:state.source,question:q,mode,aggregate:a,grouped};if(kind==="json")exportBlob(`Analyse_Question_${state.role}_${timestamp()}.json`,JSON.stringify(obj,null,2),'application/json;charset=utf-8');else{let rows=[["Question",q.label],["Type",q.analysisType],["Mode",mode]];if(grouped.length){rows.push([], [mode,"Réponses","Total groupe","Taux de réponse","Indicateur"], ...grouped.map(x=>[x.group,x.n,x.total,fmtPct(x.rate),x.detail]));}else{rows.push([], ["Modalité","Effectif","Part"], ...distEntries(a).map(([v,n])=>[v,n,fmtPct(n/Math.max(1,a.n))]));}exportBlob(`Analyse_Question_${state.role}_${timestamp()}.csv`,csv(rows),'text/csv;charset=utf-8');}}
function downloadQuestionChart(){const c=state.charts.chartQuestion;if(!c)return toast("Aucun graphique disponible.","error");const a=document.createElement('a');a.href=c.toBase64Image('image/png',1);a.download=`Graphique_Question_${state.role}_${timestamp()}.png`;a.click();}
function exportFiltered(kind){if(!state.records)return toast("Chargez d’abord une source détaillée.","error");const rows=state.filteredRecords||[];const cfg=CONFIG[state.role];if(kind==="json")exportBlob(`Recherche_${state.role}_${timestamp()}.json`,JSON.stringify(rows,null,2),'application/json;charset=utf-8');else{const data=[["ID","Date","DREN","CISCO","ZAP"],...rows.map(r=>[r.id,recordVal(r,"LOCALISATION/DATE_ENQ"),recordVal(r,cfg.geoPaths.DREN),recordVal(r,cfg.geoPaths.CISCO),state.role==="ZAP"?recordVal(r,cfg.geoPaths.ZAP):""])];exportBlob(`Recherche_${state.role}_${timestamp()}.csv`,csv(data),'text/csv;charset=utf-8');}}

function setRole(role){if(!CONFIG[role]||role===state.role)return;state.role=role;state.records=null;state.filteredRecords=[];state.source="snapshot";document.querySelectorAll('.role-card').forEach(b=>b.classList.toggle('active',b.dataset.role===role));populateQuestionControls(false);populateCatalogFilters();setTerritorialScope("DREN");useSnapshot();}
function setTerritorialScope(scope){
  if(!["DREN","CISCO","ZAP"].includes(scope))return;
  if(scope==="ZAP" && state.role!=="ZAP"){
    state.role="ZAP";state.records=null;state.filteredRecords=[];state.source="snapshot";
    document.querySelectorAll('.role-card').forEach(b=>b.classList.toggle('active',b.dataset.role==="ZAP"));
    populateQuestionControls(false);populateCatalogFilters();
  }
  state.scope=scope;
  document.querySelectorAll('.territorial-tab').forEach(b=>{const active=b.dataset.scope===scope;b.classList.toggle('active',active);b.setAttribute('aria-selected',active?'true':'false');});
  if($("territorialStatus"))$("territorialStatus").textContent=scope;
  if($("territorialMessage"))$("territorialMessage").innerHTML=`<strong>Onglet ${scope} actif.</strong> Les KPI, graphiques et tableaux sont recalculés autour du niveau ${scope}.`;
  if($("groupModeSelect") && state.records && CONFIG[state.role].geoPaths[scope])$("groupModeSelect").value=scope;
  renderAll();
}
function switchTab(name){document.querySelectorAll('.workspace-tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));document.querySelectorAll('.workspace-panel').forEach(p=>p.classList.toggle('active',p.id===`tab-${name}`));if(name==="catalog")renderCatalog();if(name==="question")renderQuestion();if(name==="search")renderSearchFilters();}
function renderAll(){renderDashboard();populateQuestionControls(true);updateGroupOptions();renderQuestion();renderCatalog();renderSearchFilters();}

function init(){
  $("ciscoSnapshotCount").textContent=fmtNum(DMS_DATA.meta.snapshotCounts.CISCO);$("zapSnapshotCount").textContent=fmtNum(DMS_DATA.meta.snapshotCounts.ZAP);
  document.querySelectorAll('.role-card').forEach(b=>b.addEventListener('click',()=>setRole(b.dataset.role)));
  document.querySelectorAll('.workspace-tab').forEach(b=>b.addEventListener('click',()=>switchTab(b.dataset.tab)));
  document.querySelectorAll('.territorial-tab').forEach(b=>b.addEventListener('click',()=>setTerritorialScope(b.dataset.scope)));
  $("useSnapshotBtn").addEventListener('click',useSnapshot);$("syncKoboBtn").addEventListener('click',syncKobo);$("jsonImport").addEventListener('change',e=>e.target.files[0]&&importJson(e.target.files[0]));$("refreshViewBtn").addEventListener('click',renderAll);
  $("themeSelect").addEventListener('change',()=>{populateQuestionControls(false);renderQuestion();});$("questionSelect").addEventListener('change',renderQuestion);$("groupModeSelect").addEventListener('change',renderQuestion);$("questionChartType").addEventListener('change',renderQuestion);
  $("applyFilters").addEventListener('click',applySearchFilters);$("resetFilters").addEventListener('click',resetSearch);$("catalogSearch").addEventListener('input',renderCatalog);$("catalogType").addEventListener('change',renderCatalog);$("catalogTheme").addEventListener('change',renderCatalog);
  $("exportQuestionCsv").addEventListener('click',()=>exportQuestion('csv'));$("exportQuestionJson").addEventListener('click',()=>exportQuestion('json'));$("downloadQuestionChart").addEventListener('click',downloadQuestionChart);$("exportFilteredCsv").addEventListener('click',()=>exportFiltered('csv'));$("exportFilteredJson").addEventListener('click',()=>exportFiltered('json'));
  document.querySelectorAll('[data-export]').forEach(b=>b.addEventListener('click',()=>exportDashboard(b.dataset.export)));
  populateQuestionControls(false);populateCatalogFilters();useSnapshot();
}
window.addEventListener('DOMContentLoaded',init);
